/* eslint-disable no-restricted-globals */
// Module worker: loads Pyodide + SymPy from the CDN on first use and evaluates
// expressions generated by toSympy.js. (Classic workers cannot load Pyodide
// reliably, so this must be created with { type: "module" }.)

const PYODIDE_URL = "https://cdn.jsdelivr.net/pyodide/v314.0.7/full/";

const PRELUDE = `
from sympy import *
import json

_NS = {k: v for k, v in globals().items() if not k.startswith('__')}

def _S(name):
    return Symbol(name)

_NS['_S'] = _S

def _tex(e):
    return latex(e, ln_notation=True, inv_trig_style='full')

def _calc(payload):
    p = json.loads(payload)
    op = p['op']
    expr = eval(p['src'], _NS)
    if op == 'solve':
        rhs = eval(p['src2'], _NS)
        items = solve(Eq(expr, rhs), Symbol(p['var']))
    else:
        r = expr.doit() if hasattr(expr, 'doit') else expr
        if op in ('exact', 'simplify'):
            r = simplify(r)
        elif op == 'expand':
            r = expand(r)
        elif op == 'factor':
            r = factor(r)
        items = [r]
    free = sorted({str(s) for r in items for s in getattr(r, 'free_symbols', set())})
    numeric = None
    if len(items) == 1 and not free:
        try:
            numeric = str(N(items[0], 12))
        except Exception:
            numeric = None
    return json.dumps({
        'items': [_tex(i) for i in items],
        'plain': [str(i) for i in items],
        'free': free,
        'numeric': numeric,
    })
`;

let ready = null;

async function init() {
  const { loadPyodide } = await import(/* @vite-ignore */ `${PYODIDE_URL}pyodide.mjs`);
  const py = await loadPyodide({ indexURL: PYODIDE_URL });
  await py.loadPackage("sympy");
  await py.runPythonAsync(PRELUDE);
  self.postMessage({ type: "status", status: "ready" });
  return py;
}

self.onmessage = async (e) => {
  const { id, payload } = e.data;
  try {
    if (!ready) ready = init();
    const py = await ready;
    const out = py.globals.get("_calc")(JSON.stringify(payload));
    self.postMessage({ id, ok: true, result: JSON.parse(out) });
  } catch (err) {
    // Python tracebacks are long: keep the last meaningful line.
    const msg = String((err && err.message) || err).trim().split("\n").filter(Boolean).pop() || "Failed";
    self.postMessage({ id, ok: false, error: msg });
  }
};
